if($env:USERNAME-ne'KoettLab'-or$env:COMPUTERNAME-ne'KOETT-LAB'){throw 'These checks run only in the isolated Koett Windows lab guest'}
$ErrorActionPreference='Stop';Start-Sleep -Milliseconds 700;$stop=Run-MediaCli 'stop';$null=Wait-MediaDone;Start-Sleep -Milliseconds 800
$overlay=[LabDriver]::ByClass('KoettOverlayWindow');$actions=@([Windows.Automation.AutomationElement]::FromHandle($overlay).FindAll([Windows.Automation.TreeScope]::Children,[Windows.Automation.Condition]::TrueCondition)|ForEach-Object {$_.Current.Name});$info=Invoke-LabButton $overlay 'Copy';$text=[Windows.Forms.Clipboard]::GetText();$formats=@([Windows.Forms.Clipboard]::GetDataObject().GetFormats());$step=Get-LabStep 'image-only-pin-copy';$h=[LabDriver]::ByTitle('M6 private words target');if($h-ne[IntPtr]::Zero){$null=[LabDriver]::PostMessage($h,0x10,[IntPtr]::Zero,[IntPtr]::Zero)}
@{passed=($text-match'Image only · page details off'-and$text-notmatch'M6_SELECTED_SECRET|M6 private words target'-and'PNG'-in$formats);text=$text;formats=$formats;actions=$actions;copy=$info;stop=$stop;step=$step;artifact=Get-LabArtifact;focus=Get-LabFocus}
